/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=organization, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2OrganizationGetParams = {
  resource: 'organization';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the organization to get
 * @default 0
 */
    organizationId?: number | Expression<number>;
/**
 * Whether to show raw Pipedrive field keys and option IDs instead of human-readable names in output
 * @default false
 */
    rawCustomFieldOutput?: boolean | Expression<boolean>;
};

export type PipedriveV2OrganizationGetOutput = {
  add_time?: string;
  address?: unknown;
  annual_revenue?: unknown;
  custom_fields?: Record<string, unknown>;
  employee_count?: unknown;
  id?: number;
  industry?: unknown;
  is_deleted?: boolean;
  label_ids?: Array<unknown>;
  linkedin?: unknown;
  name?: string;
  owner_id?: number;
  update_time?: string;
  visible_to?: number;
  website?: unknown;
};

export type PipedriveV2OrganizationGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2OrganizationGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2OrganizationGetOutput>;
};